def format_size(num_bytes: int) -> str:
    """Formatiert eine Byte-Anzahl menschenlesbar (z.B. ``1.44 GB``)."""
    size = float(num_bytes)
    for unit in _SIZE_UNITS:
        if size < 1024.0:
            if unit == "B":
                return f"{int(size)} {unit}"
            return f"{size:.2f} {unit}"
        size /= 1024.0
    return f"{size:.2f} EB"

